  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "A close tropane analog showed high, rapid striatal uptake in rat PET imaging, demonstrating efficient BBB penetration for the tropane scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A tropane-based PET ligand achieved 3.23% ID/g in rat striatum at 5 min and was labeled as good penetration, confirming efficient BBB passage for N-methyl tropane esters.",
